from cardio_1 import a as _register, G

def a(key, *args):
    if key not in G:
        _register(key, *args)

# E10 : clés locales, sans écrasement d’une définition globale.
a('HbA1c — E10', [('HbA1c', 'Hémoglobine glyquée A1c')], 'Hémoglobine glyquée A1c', '<p>Fraction glyquée de l’hémoglobine : elle renseigne sur une exposition prolongée au glucose, mais dépend aussi des globules rouges. Le type 1 aigu ne se diagnostique pas sur cette valeur seule.</p><p class="src">Sources : <a href="https://www.sgedssed.ch/SgedSsed/fileadmin/6_Diabetologie/62_Empfehlungen_Hausarzt/Position-SGED_Diagnose-mit-HbA1c_2011_FR_1_.pdf" target="_blank" rel="noopener">SSED — diagnostic du diabète avec l’HbA1c — 2011</a>.</p>', 'e10-gl-1')
a('SSED — E10', [('SSED', 'Société suisse d’endocrinologie et de diabétologie')], 'Société suisse d’endocrinologie et de diabétologie', '<p>Société savante suisse, SGED en allemand ; ses textes nationaux sont prioritaires dans ce cours.</p><p class="src">Sources : <a href="https://www.sgedssed.ch/SgedSsed/fileadmin/6_Diabetologie/61_Empfehlungen_Facharzt/2025_Swiss_Diabetes_and_Technology_Recommendations_inkl_Table_E.pdf" target="_blank" rel="noopener">SSED — recommandations suisses sur les technologies du diabète — 25 février 2025</a>.</p>', 'e10-gl-2')
a('NICE — E10', [('NICE', 'National Institute for Health and Care Excellence')], 'National Institute for Health and Care Excellence', '<p>Organisme britannique d’évaluation et de recommandations ; NG17 concerne le diabète de type 1 de l’adulte.</p><p class="src">Sources : <a href="https://www.nice.org.uk/guidance/ng17/chapter/Recommendations" target="_blank" rel="noopener">NICE NG17 — Type 1 diabetes in adults — recommandations avec amendements 2022, page consultée le 13 octobre 2026</a>.</p>', 'e10-gl-3')
a('JBDS — E10', [('JBDS', 'Joint British Diabetes Societies')], 'Joint British Diabetes Societies', '<p>Sociétés britanniques de diabétologie ; les protocoles hospitaliers adultes de 2023 sont identifiés séparément des textes suisses.</p><p class="src">Sources : <a href="https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_02_DKA_Guideline_with_QR_code_March_2023.pdf" target="_blank" rel="noopener">JBDS — The Management of Diabetic Ketoacidosis in Adults — mars 2023</a>.</p>', 'e10-gl-4')
a('FI — E10', [('FI', 'Information professionnelle')], 'Information professionnelle', '<p>Texte approuvé pour un médicament suisse précis : indication, forme, dose, voies et populations ne doivent pas être déduites d’une autre présentation.</p><p class="src">Sources : <a href="https://amiko.oddb.org/fr/fi?gtin=7680550450024" target="_blank" rel="noopener">Swissmedic — NovoRapid, information professionnelle — avril 2026</a>.</p>', 'e10-gl-5')
a('CGM — E10', [('CGM', 'Continuous glucose monitoring — mesure continue du glucose')], 'Continuous glucose monitoring — mesure continue du glucose', '<p>Le capteur mesure le glucose interstitiel ; il fournit des tendances et des durées dans différentes plages, avec des limites de données et de délai.</p><p class="src">Sources : <a href="https://www.sgedssed.ch/SgedSsed/fileadmin/6_Diabetologie/61_Empfehlungen_Facharzt/2025_Swiss_Diabetes_and_Technology_Recommendations_inkl_Table_E.pdf" target="_blank" rel="noopener">SSED — recommandations suisses sur les technologies du diabète — 25 février 2025</a>.</p>', 'e10-gl-6')
a('AID — E10', [('AID', 'Automated insulin delivery — administration automatisée d’insuline')], 'Automated insulin delivery — administration automatisée d’insuline', '<p>Association capteur, algorithme et pompe ; elle nécessite apprentissage, compatibilité et plan de secours.</p><p class="src">Sources : <a href="https://www.sgedssed.ch/SgedSsed/fileadmin/6_Diabetologie/61_Empfehlungen_Facharzt/2025_Swiss_Diabetes_and_Technology_Recommendations_inkl_Table_E.pdf" target="_blank" rel="noopener">SSED — recommandations suisses sur les technologies du diabète — 25 février 2025</a>.</p>', 'e10-gl-7')
a('TIR — E10', [('TIR', 'Time in range — temps dans la plage cible')], 'Time in range — temps dans la plage cible', '<p>Proportion du temps mesuré dans la plage choisie ; la plage et la population doivent être indiquées.</p><p class="src">Sources : <a href="https://www.sgedssed.ch/SgedSsed/fileadmin/6_Diabetologie/61_Empfehlungen_Facharzt/2025_Swiss_Diabetes_and_Technology_Recommendations_inkl_Table_E.pdf" target="_blank" rel="noopener">SSED — recommandations suisses sur les technologies du diabète — 25 février 2025</a>.</p>', 'e10-gl-8')
a('TBR — E10', [('TBR', 'Time below range — temps sous la plage')], 'Time below range — temps sous la plage', '<p>Mesure de l’exposition aux concentrations basses ; elle complète le temps dans la cible.</p><p class="src">Sources : <a href="https://www.sgedssed.ch/SgedSsed/fileadmin/6_Diabetologie/61_Empfehlungen_Facharzt/2025_Swiss_Diabetes_and_Technology_Recommendations_inkl_Table_E.pdf" target="_blank" rel="noopener">SSED — recommandations suisses sur les technologies du diabète — 25 février 2025</a>.</p>', 'e10-gl-9')
a('AGP — E10', [('AGP', 'Ambulatory glucose profile — profil glycémique ambulatoire')], 'Ambulatory glucose profile — profil glycémique ambulatoire', '<p>Présentation standardisée des données du capteur. Un simple tracé de 24 heures n’est pas à lui seul un rapport AGP complet.</p><p class="src">Sources : <a href="https://www.sgedssed.ch/SgedSsed/fileadmin/6_Diabetologie/61_Empfehlungen_Facharzt/2025_Swiss_Diabetes_and_Technology_Recommendations_inkl_Table_E.pdf" target="_blank" rel="noopener">SSED — recommandations suisses sur les technologies du diabète — 25 février 2025</a>.</p>', 'e10-gl-10')
a('LADA — E10', [('LADA', 'Latent autoimmune diabetes in adults')], 'Latent autoimmune diabetes in adults', '<p>Présentation auto-immune lente de l’adulte ; ni l’âge ni le surpoids n’excluent un mécanisme auto-immun.</p><p class="src">Sources : <a href="https://www.nice.org.uk/guidance/ng17/chapter/Recommendations" target="_blank" rel="noopener">NICE NG17 — Type 1 diabetes in adults — recommandations avec amendements 2022, page consultée le 13 octobre 2026</a>.</p>', 'e10-gl-11')
a('ATP — E10', [('ATP', 'Adénosine triphosphate')], 'Adénosine triphosphate', '<p>Molécule du métabolisme énergétique. Dans la cellule β, le rapport ATP/ADP participe au couplage glucose–sécrétion.</p><p class="src">Sources : <a href="https://www.mdpi.com/1422-0067/20/6/1351" target="_blank" rel="noopener">Kostov — Effects of magnesium deficiency on insulin resistance — 18 mars 2019</a>.</p>', 'e10-gl-12')
a('ADP — E10', [('ADP', 'Adénosine diphosphate')], 'Adénosine diphosphate', '<p>Molécule comparée à l’ATP dans le rapport énergétique ; un rapport de concentrations dans la même unité est sans dimension.</p><p class="src">Sources : <a href="https://www.mdpi.com/1422-0067/20/6/1351" target="_blank" rel="noopener">Kostov — Effects of magnesium deficiency on insulin resistance — 18 mars 2019</a>.</p>', 'e10-gl-13')
a('GLUT4 — E10', [('GLUT4', 'Transporteur du glucose de type 4')], 'Transporteur du glucose de type 4', '<p>Le signal insulinique favorise sa présence à la membrane du muscle et du tissu adipeux.</p><p class="src">Sources : <a href="https://www.mdpi.com/1422-0067/20/6/1351" target="_blank" rel="noopener">Kostov — Effects of magnesium deficiency on insulin resistance — 18 mars 2019</a>.</p>', 'e10-gl-14')
a('IRS — E10', [('IRS', 'Insulin receptor substrate — substrat du récepteur de l’insuline')], 'Insulin receptor substrate — substrat du récepteur de l’insuline', '<p>Relais intracellulaire du signal du récepteur vers les voies métaboliques.</p><p class="src">Sources : <a href="https://www.mdpi.com/1422-0067/20/6/1351" target="_blank" rel="noopener">Kostov — Effects of magnesium deficiency on insulin resistance — 18 mars 2019</a>.</p>', 'e10-gl-15')
a('PI3K — E10', [('PI3K', 'Phosphatidylinositol 3-kinase')], 'Phosphatidylinositol 3-kinase', '<p>Enzyme de la cascade de signalisation insulinique conduisant notamment à l’activation d’Akt.</p><p class="src">Sources : <a href="https://www.mdpi.com/1422-0067/20/6/1351" target="_blank" rel="noopener">Kostov — Effects of magnesium deficiency on insulin resistance — 18 mars 2019</a>.</p>', 'e10-gl-16')
a('Akt — E10', [('Akt', 'Kinase Akt')], 'Kinase Akt', '<p>Nom de protéine, et non mot à développer lettre par lettre ; elle relaie des effets métaboliques de l’insuline.</p><p class="src">Sources : <a href="https://www.mdpi.com/1422-0067/20/6/1351" target="_blank" rel="noopener">Kostov — Effects of magnesium deficiency on insulin resistance — 18 mars 2019</a>.</p>', 'e10-gl-17')
a('HMG-CoA — E10', [('HMG-CoA', 'Hydroxy-méthyl-glutaryl-coenzyme A')], 'Hydroxy-méthyl-glutaryl-coenzyme A', '<p>Intermédiaire nommé dans la voie de cétogenèse hépatique ; le contexte mitochondrial doit être conservé.</p><p class="src">Sources : <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC8656040/" target="_blank" rel="noopener">Kolb et al. — Ketone bodies: from enemy to friend and guardian angel — 9 décembre 2021</a>.</p>', 'e10-gl-18')
a('SCOT — E10', [('SCOT', 'Succinyl-CoA:3-oxoacide CoA-transférase')], 'Succinyl-CoA:3-oxoacide CoA-transférase', '<p>Enzyme nécessaire à une étape de l’utilisation des corps cétoniques par les tissus extra-hépatiques.</p><p class="src">Sources : <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC8656040/" target="_blank" rel="noopener">Kolb et al. — Ketone bodies: from enemy to friend and guardian angel — 9 décembre 2021</a>.</p>', 'e10-gl-19')
a('HLA — E10', [('HLA', 'Human leukocyte antigen — antigènes leucocytaires humains')], 'Human leukocyte antigen — antigènes leucocytaires humains', '<p>Molécules de présentation antigénique ; certains variants sont associés à une susceptibilité, sans constituer un diagnostic individuel.</p><p class="src">Sources : <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC11703732/" target="_blank" rel="noopener">Revue — B cells in type 1 diabetes — 2024, article avec correction 2026</a>.</p>', 'e10-gl-20')
a('NOD — E10', [('NOD', 'Non-obese diabetic — souris diabétique non obèse')], 'Non-obese diabetic — souris diabétique non obèse', '<p>Modèle expérimental d’auto-immunité ; ses observations ne doivent pas être assimilées sans vérification aux effets cliniques humains.</p><p class="src">Sources : <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC11703732/" target="_blank" rel="noopener">Revue — B cells in type 1 diabetes — 2024, article avec correction 2026</a>.</p>', 'e10-gl-21')
a('GAD — E10', [('GAD', 'Glutamate décarboxylase')], 'Glutamate décarboxylase', '<p>Antigène de la cellule β ; les anticorps dirigés contre cette enzyme peuvent soutenir une étiologie auto-immune.</p><p class="src">Sources : <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC12730728/" target="_blank" rel="noopener">Kandinov et al. — Molecular Portrait of Type 1 Diabetes — 11 décembre 2025</a>.</p>', 'e10-gl-22')
a('IA-2 — E10', [('IA-2', 'Insulinoma-associated antigen 2')], 'Insulinoma-associated antigen 2', '<p>Antigène associé aux granules des cellules β ; cible d’autoanticorps.</p><p class="src">Sources : <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC12730728/" target="_blank" rel="noopener">Kandinov et al. — Molecular Portrait of Type 1 Diabetes — 11 décembre 2025</a>.</p>', 'e10-gl-23')
a('ZnT8 — E10', [('ZnT8', 'Transporteur du zinc de type 8')], 'Transporteur du zinc de type 8', '<p>Protéine des granules β, cible d’autoanticorps ; sa représentation dans une figure n’est pas un dosage sanguin.</p><p class="src">Sources : <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC12730728/" target="_blank" rel="noopener">Kandinov et al. — Molecular Portrait of Type 1 Diabetes — 11 décembre 2025</a>.</p>', 'e10-gl-24')
a('IV — E10', [('IV', 'Intraveineux')], 'Intraveineux', '<p>Voie d’administration dans une veine, autorisée uniquement pour les produits et préparations correspondants ; surveillance professionnelle.</p><p class="src">Sources : <a href="https://amiko.oddb.org/fr/fi?gtin=7680550450024" target="_blank" rel="noopener">Swissmedic — NovoRapid, information professionnelle — avril 2026</a>.</p>', 'e10-gl-25')
a('IM — E10', [('IM', 'Intramusculaire')], 'Intramusculaire', '<p>Voie d’administration dans un muscle ; elle est notamment exclue pour Tresiba.</p><p class="src">Sources : <a href="https://amiko.oddb.org/fr/fi?gtin=7680625620017" target="_blank" rel="noopener">Swissmedic — Tresiba, information professionnelle — décembre 2024</a>.</p>', 'e10-gl-26')
a('TA — E10', [('TA', 'Trou anionique')], 'Trou anionique', '<p>Résidu calculé entre cations et anions mesurés ; la formule avec potassium et celle sans potassium ne se comparent pas à la même référence.</p><p class="src">Sources : <a href="https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_02_DKA_Guideline_with_QR_code_March_2023.pdf" target="_blank" rel="noopener">JBDS — The Management of Diabetic Ketoacidosis in Adults — mars 2023</a>.</p>', 'e10-gl-27')
a('mOsm — E10', [('mOsm', 'Milliosmole')], 'Milliosmole', '<p>Unité de quantité osmotique ; l’osmolalité s’exprime ici en mOsm/kg et doit être distinguée d’une concentration de glucose.</p><p class="src">Sources : <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10107355/" target="_blank" rel="noopener">JBDS — Management of hyperosmolar hyperglycaemic state in adults — 2023</a>.</p>', 'e10-gl-28')
a('HUG — E10', [('HUG', 'Hôpitaux universitaires de Genève')], 'Hôpitaux universitaires de Genève', '<p>Institution suisse dont le protocole d’hypoglycémie hospitalière est cité avec sa population et sa version.</p><p class="src">Sources : <a href="https://www.hug.ch/vdoc/HUG_000000812.pdf" target="_blank" rel="noopener">HUG — Hypoglycémie, prise en charge — 2 septembre 2022, version 1.0</a>.</p>', 'e10-gl-29')
a('RMS — E10', [('RMS', 'Revue Médicale Suisse')], 'Revue Médicale Suisse', '<p>Publication suisse ; la fiche de crises hyperglycémiques de 2019 sert ici à préciser l’orientation locale.</p><p class="src">Sources : <a href="https://www.revmed.ch/view/415288/3626033/RMS_639_449.pdf" target="_blank" rel="noopener">Revue Médicale Suisse — crises hyperglycémiques — 2019, volume 639, p. 449</a>.</p>', 'e10-gl-30')
a('SGRM — E10', [('SGRM', 'Schweizerische Gesellschaft für Rechtsmedizin — Société suisse de médecine légale')], 'Schweizerische Gesellschaft für Rechtsmedizin — Société suisse de médecine légale', '<p>Cosignataire des recommandations suisses sur diabète et conduite ; les catégories de permis et le risque d’hypoglycémie déterminent l’évaluation.</p><p class="src">Sources : <a href="https://www.sgedssed.ch/SgedSsed/fileadmin/6_Diabetologie/61_Empfehlungen_Facharzt/Handout_Richtlinien_Diabetes_DE_Version_1_August_2025.pdf" target="_blank" rel="noopener">SSED / médecine légale — diabète et conduite — 1 août 2025</a>.</p>', 'e10-gl-31')
a('KATP — E10', [('KATP', 'Canal potassique sensible à l’ATP')], 'Canal potassique sensible à l’ATP', '<p>Canal qui relie état énergétique et potentiel de membrane dans le couplage de la sécrétion d’insuline. Sa fermeture favorise la dépolarisation.</p><p class="src">Sources : <a href="https://www.mdpi.com/1422-0067/20/6/1351" target="_blank" rel="noopener">Kostov — Effects of magnesium deficiency on insulin resistance — 18 mars 2019</a>.</p>', 'e10-gl-32')
a('acétyl-CoA — E10', [('acétyl-CoA', 'Acétyl-coenzyme A')], 'Acétyl-coenzyme A', '<p>Intermédiaire issu notamment de la β-oxydation ; dans le foie, il peut alimenter la production de corps cétoniques.</p><p class="src">Sources : <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC8656040/" target="_blank" rel="noopener">Kolb et al. — Ketone bodies: from enemy to friend and guardian angel — 9 décembre 2021</a>.</p>', 'e10-gl-33')
a('succinyl-CoA — E10', [('succinyl-CoA', 'Succinyl-coenzyme A')], 'Succinyl-coenzyme A', '<p>Composé participant à la réaction catalysée par SCOT dans la cétolyse extra-hépatique.</p><p class="src">Sources : <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC8656040/" target="_blank" rel="noopener">Kolb et al. — Ketone bodies: from enemy to friend and guardian angel — 9 décembre 2021</a>.</p>', 'e10-gl-34')
a('CoA-transférase — E10', [('CoA-transférase', 'Coenzyme A-transférase')], 'Coenzyme A-transférase', '<p>Famille d’enzymes transférant un groupement coenzyme A ; SCOT désigne ici l’enzyme de la cétolyse extra-hépatique.</p><p class="src">Sources : <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC8656040/" target="_blank" rel="noopener">Kolb et al. — Ketone bodies: from enemy to friend and guardian angel — 9 décembre 2021</a>.</p>', 'e10-gl-35')
a('MAPK — E10', [('MAPK', 'Mitogen-activated protein kinase — kinase activée par les mitogènes')], 'Mitogen-activated protein kinase — kinase activée par les mitogènes', '<p>Branche de signalisation liée notamment à l’expression des gènes et aux effets mitogènes de l’insuline ; distincte de PI3K–Akt.</p><p class="src">Sources : <a href="https://www.mdpi.com/1422-0067/20/6/1351" target="_blank" rel="noopener">Kostov — Effects of magnesium deficiency on insulin resistance — 18 mars 2019</a>.</p>', 'e10-gl-36')
a('DKA — E10', [('DKA', 'Diabetic ketoacidosis — acidocétose diabétique')], 'Diabetic ketoacidosis — acidocétose diabétique', '<p>Sigle anglais présent dans les sources : associer glucose ou diabète connu, cétones et acidose selon la version du référentiel, sans traduire le sigle en un nouveau critère.</p><p class="src">Sources : <a href="https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_02_DKA_Guideline_with_QR_code_March_2023.pdf" target="_blank" rel="noopener">JBDS — The Management of Diabetic Ketoacidosis in Adults — mars 2023</a>.</p>', 'e10-gl-37')
a('HCO₃ — E10', [('HCO₃', 'Bicarbonate')], 'Bicarbonate', '<p>Notation chimique du bicarbonate ; HCO₃⁻ porte une charge négative. Le bicarbonate sérique et celui de gazométrie doivent garder leur méthode et leur unité.</p><p class="src">Sources : <a href="https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_02_DKA_Guideline_with_QR_code_March_2023.pdf" target="_blank" rel="noopener">JBDS — The Management of Diabetic Ketoacidosis in Adults — mars 2023</a>.</p>', 'e10-gl-38')
